INSERT INTO public.book_sources (id, title, source_json, description, install_id, created_at, updated_at, user_id, supported_types, source_code, review_status, review_note, reviewed_by, reviewed_at, visibility, enabled, last_test_status, last_test_at, last_test_message, origin_source_id) VALUES ('src_f49b5d8b1f7b', '番茄小说', '[{"jsLib":"\nfunction zdym(){\nlet zdymConfig; try{zdymConfig = this.source.getLoginInfoMap().get(\"自定域名\")}catch(e){}\n   let mrym = \"http:\/\/full.gxom.cn\";\nif (zdymConfig && zdymConfig != \"\") {\n    mrym = ''http:\/\/'' + zdymConfig;\n}\nreturn mrym;\n}\n\nfunction jsmy() {\nlet jsmy = String(this.cookie.getCookie(this.zdym()).match(\/qdkey=([^;]*)\/)?.[1] || '''');\nreturn jsmy;\n}\n\nfunction getComments(content, bid, cid, version) {\n    const { java, cache } = this;\n    try {\n        let comments = java.ajax(`{{this.zdym()}}\/fanqie\/fqdlsj.php?item_id=${cid}&version=${version}`);\n        let raw = JSON.parse(comments).data.data;\n        \/\/ 核心修改：将 <\/p> 作为段落分隔符，同时保留 img 标签不被拆分\n        let comcont = content.replace(\/(<img[^>]*?>)<\\\/p>\/g, \"$1<\/p>\").split(\"<\/p>\");\n        \n        Object.keys(raw).forEach((x) => {\n            cache.putMemory(`fq-${bid}-${cid}-${x}-text`, comcont[x]);\n            if (comcont[x]) {\n                comcont[x] += `<img src =\"${this.createSvg(raw[x].count, bid, cid, x, version)}\">`;\n            }\n        });\n        return comcont.join(\"\\n\");\n    } catch (e) {\n        java.log(e);\n        return content;\n    }\n}\n\nfunction createSvg(number, bid, cid, para, version) {\n    let displayText = number > 99 ? \"99+\" : number;\n    let date = Date.now().toString();\n\n    let colorValue = this.source.getLoginInfoMap().get(\"气泡颜色\");\n    let ys = colorValue?.includes(\"#\") ? String(colorValue) : \"#0000ff\";\n\n    let svg = `<svg width=\"1000\" height=\"800\" xmlns=\"http:\/\/www.w3.org\/2000\/svg\">\n        <rect x=\"240\" y=\"240\" width=\"750\" height=\"550\" rx=\"250\" ry=\"250\" fill=\"none\" stroke=\"${ys}\" stroke-width=\"25\"\/>\n        <text x=\"610\" y=\"620\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\" dominant-baseline=\"middle\" font-size=\"300\" fill=\"${ys}\">${displayText}<\/text>\n    <\/svg>`;\n\n    let encodedSvg = this.java.base64Encode(svg);\n    return `data:image\/svg+xml;base64,${encodedSvg},{\"style\":\"text\",\"type\":\"fq\",\"js\":\"showCmt(''${bid}'', ''${cid}'', ''${para}'', ''${version}'', ''${date}'')\"}`;\n}\n\nfunction showCmt(bid, cid, para, version, date) {\n    const { java, cache } = this;\n    var mname = `fq-${bid}-${cid}-${para}`;\n    var cname = \"item_id\";\n    var pname = \"para\";\n\n    let load = (cache.getFromMemory(mname) ?? \"-\").split(\"-\");\n    if (load[0] != \"1\" || load[1] != date) {\n        cache.putMemory(mname, \"1-\" + date);\n        return;\n    }\n\n    let apiUrl = `{{this.zdym()}}\/fanqie\/fqdlpl.php?${cname}=${cid}&book_id=${bid}&${pname}=${para}&version=${version}`;\n    let title = cache.getFromMemory(mname + \"-text\") ?? \"fqphp_段落评论\";\n\n    java.startBrowser(apiUrl, title);\n}","ruleSearch":{"author":"author","kind":"mmfl","coverUrl":"src","bookList":"$.data.books[*]","bookUrl":"url","intro":"intro","name":"name","checkKeyWord":"系统"},"weight":60,"enabled":true,"ruleToc":{"chapterName":"title","chapterList":"@js:\nfunction deviceType() {\n  try {\n    return !!java.deviceID();\n  } catch (e) {\n    return false;\n  }\n}\nlet device = deviceType() ? ''ios'' : ''android'';\njava.put(\"dev\", device);\nchapters = JSON.parse(result).data.lists;\nchapters.reduce((arr, item) => {\n  let title = item.title\n  let url = `data:;base64,${java.base64Encode(item.url)},{\"type\":\"fanqie\"}`\n  arr.push({ title, url})\n  return arr\n}, [])","chapterUrl":"url "},"ruleContent":{"content":"@js:\nlet url = java.hexDecodeToString(result);\nlet response = java.ajax( url + \"&pt=yy&key=\" + jsmy()\n);\nlet content = JSON.parse(response).data.content;\nif (java.get(\"d