    },
    "searchUrl": "@js:\nvar tab;\ntype = source.get(''type'');\nvar processedType = String(type).replace(/^\\s+|\\s+$/g, '''').toLowerCase();\nif (!type || type == \"undefined\") {\n    tab = 3;\n} else {\n    switch(processedType) {\n        case ''novel'':\n            tab = 3;\n            break;\n        case ''novelaudio'':\n            tab = 3;\n            break;\n        case ''audio'':\n            tab = 2;\n            break;\n        case ''comic'':\n            tab = 8;\n            break;\n        case ''video'':\n            tab = 11;\n            break;\n        default:\n            tab = 3;\n            break;\n    }\n}\nif (String(key).startsWith(\"n:\") || String(key).startsWith(\"n：\")) {\n    tab = 3\n    source.put(''type'',''novel'')\n    key = key.slice(2)\n}\nif (String(key).startsWith(\"m:\") || String(key).startsWith(\"m：\")) {\n    tab = 8\n    source.put(''type'',''comic'')\n    key = key.slice(2)\n}\nif (String(key).startsWith(\"t:\") || String(key).startsWith(\"t：\")) {\n    tab = 2\n    source.put(''type'',''audio'')\n    key = key.slice(2)\n}\nif (String(key).startsWith(\"d:\") || String(key).startsWith(\"d：\")) {\n    tab = 11\n    source.put(''type'',''video'')\n    key = key.slice(2)\n}\nif (key.length == 19 && !Number.isNaN(parseInt(key))) {\n    result = source.key + ''/detail?bookid='' + key\n} else {\n    result = source.key + ''/search?query='' + encodeURI(java.put(\"key\", key)) + ''&offset='' + ((java.put(\"page\", page) - 1) * 10) + ''&tab_type='' + tab\n}",
