    "loginUi": "[\n{\n        \"name\":  \"🍅番茄账号登录🍅\",\n        \"type\": \"button\",\n        \"action\": \"Y(true)\",\n        \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.4\n    }\n  },{\n        \"name\":  \"🍅退出登录🍅\",\n        \"type\": \"button\",\n        \"action\": \"X()\",\n        \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.4\n    }\n  },\n { name: \"发现类型设置\", type: \"button\", action: \"login(''【可选类型】'' + n(2) + ''[0]女生[1]男生[2]出版[3]听书[5]漫画[6]短剧\\\\n多个分类用逗号隔开'')\", style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}},\n  { name: \"分类：\", type: \"text\" },\n{\n    ''name'': ''修改类型'',\n    ''type'': ''button'',\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 1\n    }\n},\n{\n        name: \"小说\",\n        type: \"button\",\n        action: \"configs(''小说'')\",\n    \t\t style: {\n    \t\t \tlayout_flexGrow: 1,\n    \t\t \tlayout_flexBasisPercent: 0.4\n    \t\t \t}\n},\n{\n        name: \"漫画\",\n        type: \"button\",\n        action: \"configs(''漫画'')\",\n    \t\t style: {\n    \t\t \tlayout_flexGrow: 1,\n    \t\t \tlayout_flexBasisPercent: 0.4\n    \t\t \t}\n},\n{\n        name: \"小说听书\",\n        type: \"button\",\n        action: \"configs(''小说听书'')\",\n    \t\t style: {\n    \t\t \tlayout_flexGrow: 1,\n    \t\t \tlayout_flexBasisPercent: 0.4\n    \t\t \t}\n},\n{\n        name: \"真人听书\",\n        type: \"button\",\n        action: \"configs(''真人听书'')\",\n    \t\t style: {\n    \t\t \tlayout_flexGrow: 1,\n    \t\t \tlayout_flexBasisPercent: 0.4\n    \t\t \t}\n},\n{\n        name: \"短剧\",\n        type: \"button\",\n        action: \"configs(''短剧'')\",\n    \t\t style: {\n    \t\t \tlayout_flexGrow: 1,\n    \t\t \tlayout_flexBasisPercent: 0.4\n    \t\t \t}\n},\n{\n    ''name'': ''修改听书音色'',\n    ''type'': ''button'',\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 1\n    }\n  },\n  { name: \"自定义音色：\", type: \"text\" },\n  {\n    \"name\": \"多人对话\",\n    \"type\": \"button\",\n    \"action\": \"setTone(1)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"真人主播\",\n    \"type\": \"button\",\n    \"action\": \"setTone(2)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"甜美少女\",\n    \"type\": \"button\",\n    \"action\": \"setTone(3)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"清亮青叔\",\n    \"type\": \"button\",\n    \"action\": \"setTone(4)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"成熟大叔\",\n    \"type\": \"button\",\n    \"action\": \"setTone(5)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"开朗青年\",\n    \"type\": \"button\",\n    \"action\": \"setTone(6)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"温柔淑女\",\n    \"type\": \"button\",\n    \"action\": \"setTone(7)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"风雅青叔\",\n    \"type\": \"button\",\n    \"action\": \"setTone(8)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"清纯少女\",\n    \"type\": \"button\",\n    \"action\": \"setTone(9)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"磁性青叔\",\n    \"type\": \"button\",\n    \"action\": \"setTone(10)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"儒雅大叔\",\n    \"type\": \"button\",\n    \"action\": \"setTone(11)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"优雅御姐\",\n    \"type\": \"button\",\n    \"action\": \"setTone(12)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"斯文青叔\",\n    \"type\": \"button\",\n    \"action\": \"setTone(13)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"知性主播\",\n    \"type\": \"button\",\n    \"action\": \"setTone(14)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"成熟升级\",\n    \"type\": \"button\",\n    \"action\": \"setTone(15)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"多人升级\",\n    \"type\": \"button\",\n    \"action\": \"setTone(16)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"俏皮御姐\",\n    \"type\": \"button\",\n    \"action\": \"setTone(17)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  },\n  {\n    \"name\": \"双音灵动\",\n    \"type\": \"button\",\n    \"action\": \"setTone(18)\",\n    \"style\": {\n      \"layout_flexGrow\": 1,\n      \"layout_flexBasisPercent\": 0.25\n    }\n  }\n]",
    "loginUrl": "function login(e) {\n    if (e == undefined) {\n        return;\n    }\n    java.longToast(e);\n}\nfunction n(e) {\n    n = ''\\n'';\n    for (m = 1; m < e; m++) {\n        n = n + ''\\n'';\n    }\n    return n;\n}\nfunction login_(openBrowser, checkMode) {\n    // java.removeCookie(\"snssdk.com\")\n    var cookie_ = String(cookie.getKey(\"fanqienovel.com\", \"sessionid\")) ? String(cookie.getKey(\"fanqienovel.com\", \"sessionid\")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})[''手动登录Token'']\n    // java.toast(cookie_)\n    if (cookie_ && cookie_ != \"\" && !checkMode) {\n        if (!source.variableComment) {\n            java.toast(\"请不要重复登录，请先退出登录！\")\n        } else {\n            java.toast(\"您为填写token登录，请手动移除token后再次登录\")\n        }\n        return false\n    }\n    if (openBrowser) {\n        try {\n            java.startBrowserAwait(\"https://fanqienovel.com/\", \"登录\")\n        } catch (e) {\n            java.toast(e)\n        }\n    }\n    // java.log(\"snssdk cookie: \" + java.getCookie(\"snssdk.com\") + \"will be reomved\")\n    try {\n        cookie.removeCookie(\"snssdk.com\")\n    } catch (e) {}\n    // java.log(cookie)\n    var cookie_ = \"sessionid=\" + String(cookie.getKey(\"fanqienovel.com\", \"sessionid\")) ? String(cookie.getKey(\"fanqienovel.com\", \"sessionid\")) : (source.getLoginInfoMap())[''手动登录Token'']\n    let user\n    try {\n      user = JSON.parse(java.ajax(\"https://fanqienovel.com/api/user/info/v2,\" + JSON.stringify({\n        method: \"GET\",\n        headers: {\n          \"Cookie\": cookie_\n        }\n      }))).data.name\n     } catch (e) {java.log(e)}\n    if (!cookie_ || cookie_ == \"sessionid=\" || !user) {\n        java.toast(\"未获取到登录凭据，登录失败\")\n        return false\n    }\n    java.toast(\"欢迎 \" + user + \"\\n登录成功！\")\n    return true\n}\nfunction Y(a, b) {\n  try {\n    login_(a, b)\n  } catch (e) {\n    java.log(e+\"\\n\"+e.stack)\n  }\n}\nfunction X() {\n    cookie.removeCookie(\"fanqienovel.com\");\n    cookie.removeCookie(\"snssdk.com\");\n    if (String(cookie.getKey(\"fanqienovel.com\", \"sessionid\")) ? String(cookie.getKey(\"fanqienovel.com\", \"sessionid\")) : (source.getLoginInfoMap() ? source.getLoginInfoMap() : {})[''手动登录Token'']) java.toast(\"请手动移除填写的Token\")\n    else java.toast(\"退出登录成功\");\n}\n\n\nvar typeMap = {\n    ''小说'': ''novel'',\n    ''漫画'': ''comic'',\n    ''真人听书'': ''audio'',\n    ''短剧'': ''video'',\n    ''小说听书'': ''novelaudio''\n};\n\nfunction configs(btnText) {\n    var type = typeMap[btnText];\n    source.put(''type'', type);\n    java.toast(''已切换至'' + btnText)\n}\n\nvar toneList = [\n  [\"多人对话\", \"51\"],\n  [\"真人发音\", \"0\"],\n  [\"甜美少女\", \"1\"],\n  [\"清亮青叔\", \"2\"],\n  [\"成熟大叔\", \"4\"],\n  [\"开朗青年\", \"5\"],\n  [\"温柔淑女\", \"6\"],\n  [\"风雅青叔\", \"8\"],\n  [\"清纯少女\", \"12\"],\n  [\"磁性青叔\", \"17\"],\n  [\"儒雅大叔\", \"29\"],\n  [\"优雅御姐\", \"30\"],\n  [\"斯文青叔\", \"31\"],\n  [\"知性主播\", \"32\"],\n  [\"成熟升级\", \"74\"],\n  [\"多人升级\", \"80\"],\n  [\"俏皮御姐\", \"100\"],\n  [\"双音灵动\", \"103\"]\n]\n\nfunction setTone(index) {\n  let tone = toneList[index - 1][1]\n  source.put(''tone'', String(tone))\n  let toneName = toneList[index - 1][0]\n  java.longToast(`\\n✅听书发音已切换为：${toneName}`)\n}",
