ba(45, 157, 120, 0.4);\n}\n\n/* èªå®ä¹æ ·å¼åºå */\n.custom-style-section {\n  padding: 0 16px 16px;\n}\n\n.custom-styles-container {\n  margin-top: 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.empty-custom-styles {\n  text-align: center;\n  padding: 20px;\n  color: var(--text-secondary);\n  font-size: 13px;\n  background: var(--bg-elevated);\n  border-radius: 12px;\n  border: 1px dashed var(--border-color);\n}\n\n/* èªå®ä¹æ ·å¼å¡ç */\n.custom-style-card {\n  background: var(--bg-elevated);\n  border-radius: 12px;\n  padding: 12px;\n  border: 1px solid var(--border-color);\n}\n\n.custom-style-header {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  margin-bottom: 10px;\n}\n\n.style-name-input {\n  flex: 1;\n  padding: 6px 10px;\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--text-primary);\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: 6px;\n}\n\n.style-actions {\n  display: flex;\n  gap: 6px;\n}\n\n.style-btn {\n  width: 28px;\n  height: 28px;\n  border: none;\n  border-radius: 6px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 12px;\n  transition: all 0.2s ease;\n}\n\n.preview-btn {\n  background: rgba(45, 157, 120, 0.1);\n  color: var(--color-primary);\n}\n\n.preview-btn:hover {\n  background: rgba(45, 157, 120, 0.2);\n}\n\n.delete-btn {\n  background: rgba(244, 67, 54, 0.1);\n  color: #f44336;\n}\n\n.delete-btn:hover {\n  background: rgba(244, 67, 54, 0.2);\n}\n\n.style-code-textarea {\n  width: 100%;\n  padding: 10px;\n  font-size: 12px;\n  font-family: monospace;\n  color: var(--text-primary);\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: 8px;\n  resize: vertical;\n  min-height: 80px;\n  box-sizing: border-box;\n  margin-bottom: 10px;\n}\n\n.style-preview-small {\n  display: flex;\n  justify-content: center;\n  padding: 10px;\n  background: var(--bg-card);\