   <div class=\"setting-title\">ç®å½æ¾ç¤ºæ¥æº</div>\n          <div class=\"setting-desc\">å¼å¯åï¼ç®å½æåä¸ä¸ªç« èçæ é¢å°æ¾ç¤ºæ¥æºï¼æ¹ä¾¿æ¢æºçæ¶åå¼å¯å è½½ç®å½å¯ä»¥ç¥éæ¯åªä¸ªæ¥æº</div>\n        </div>\n        <label class=\"switch\">\n          <input type=\"checkbox\" id=\"showSourceInTocSwitch\" checked>\n          <span class=\"slider\"></span>\n        </label>\n      </div>\n    </div>\n    \n    <div class=\"tab-content\" id=\"contentSource\">\n      <div class=\"source-subtabs\">\n        <div class=\"source-subtab novel active\" id=\"subtabNovel\" data-type=\"å°è¯´\">\n          <i class=\"fas fa-book-open\"></i>\n          <span>å°è¯´</span>\n        </div>\n        <div class=\"source-subtab audio\" id=\"subtabAudio\" data-type=\"å¬ä¹¦\">\n          <i class=\"fas fa-headphones\"></i>\n          <span>å¬ä¹¦</span>\n        </div>\n        <div class=\"source-subtab comic\" id=\"subtabComic\" data-type=\"æ¼«ç»\">\n          <i class=\"fas fa-image\"></i>\n          <span>æ¼«ç»</span>\n        </div>\n        <div class=\"source-subtab drama\" id=\"subtabDrama\" data-type=\"ç­å§\">\n          <i class=\"fas fa-video\"></i>\n          <span>ç­å§</span>\n        </div>\n      </div>\n      <div class=\"selected-info\" style=\"margin-bottom: 10px; background: rgba(45, 157, 120, 0.08); border-color: rgba(45, 157, 120, 0.2);\">\n        æ¨èéæ©å¨é¨ï¼å¦éè¦æç´¢ç¹å®çèµæºå¯ä»¥æç´¢çæ¶åä½¿ç¨ <span class=\"highlight\">ä¹¦å@æ¥æº</span> è¿è¡æç´¢\n      </div>\n      <div id=\"sourceOptions\" class=\"source-options\"></div>\n      <div class=\"selected-info\" id=\"selectedInfo\">\n        å½åéä¸­: <span id=\"selectedCount\">0</span> ä¸ªæ¥æº\n      </div>\n    </div>\n    \n    <div id=\"hiddenSettings\" style=\"display: none;\">\n      <script type=\"application/json\" id=\"settingsJson\">\n        ${JSON.stringify(data || {\"å°è¯´\":\"å¨é¨\",\"å¬ä¹¦\":\"å¨é¨\",\"æ¼«ç»\":\"å¨é¨\",\"ç­å§\":\"å¨é¨\",\"æç´¢æ¨¡å¼\":\"å°è¯´\",\"æ¾ç¤ºå¾ç\":\"true\",\"å®æ´ç®ä»\":\"true\",\"åæ­¥ä¹¦æ¶\":\"false\",\"åæ­¥å¼¹çª\":\"true\",\"ç½ç»æ¨¡å¼\":\"æå¡å¨\",\"å¼ºå¶æç´¢\":\"false\",\"ç®å½æ¾ç¤ºæ¥æº\":\"true\"})}\n      </script>\n      <div id=\"settingsDiv\">\n        <span id=\"novelSource\">${(data && data.å°è¯´) || ''å¨é¨''}</span>\n        <span id=\"audioSource\">${(data && data.å¬ä¹¦) || ''å¨é¨''}</span>\n        <span id=\"comicSource\">${(data && data.æ¼«ç») || ''å¨é¨''}</span>\n        <span id=\"dramaSource\">${(data && data.ç­å§) || ''å¨é¨''}</span>\n        <span id=\"searchModeValue\">${(data && data.æç´¢æ¨¡å¼) || ''å°è¯´''}</span>\n        <span id=\"showImageSwitchValue\">${(data && data.æ¾ç¤ºå¾ç) || ''true''}</span>\n        <span id=\"fullDescSwitchValue\">${(data && data.å®æ´ç®ä») || ''true''}</span>\n        <span id=\"syncBookshelfSwitchValue\">${(data && data.åæ­¥ä¹¦æ¶) || ''false''}</span>\n        <span id=\"syncPopupSwitchValue\">${(data && data.åæ­¥å¼¹çª) || ''true''}</span>\n        <span id=\"networkModeValue\">${(data && data.ç½ç»æ¨¡å¼) || ''æå¡å¨''}</span>\n        <span id=\"forceSearchSwitchValue\">${(data && data.å¼ºå¶æç´¢) || ''false''}</span>\n        <span id=\"showSourceInTocValue\">${(data && data.ç®å½æ¾ç¤ºæ¥æº) || ''true''}</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\nconst SOURCES = ${JSON.stringify(config)};\nlet settings = ${JSON.stringify(data)};\nlet currentType = ''å°è¯´'';\n\ndocument.getElementById(''tabSource'').addEventListener(''click'', () => {\n  document.getElementById(''tabSource'').classList.add(''active'');\n  document.getElementById(''tabBookSource'').classList.remove(''active'');\n  document.getElementById(''contentSource'').classList.add(''active'');\n  document.getElementById(''contentBookSource'').classList.remove(''active'');\n});\n\ndocument.getElementById(''tabBookSource'').addEventListener(''click'', () => {\n  document.getElementById(''tabBookSource'').classList.add(''active'');\n  document.getElementById(''tabSource'').classList.remove(''active'');\n  document.getElementById(''contentBookSource'').classList.add(''active'');\n  document.getElementById(''contentSource'').classList.remove(''active'');\n});\n\nconst subtabs = document.querySelectorAll(''.source-subtab'');\nsubtabs.forEach(tab => {\n  tab.addEventListener(''click'', () => {\n    subtabs.forEach(t => t.classList.remove(''active''));\n    tab.classList.add(''active'');\n    currentType = tab.dataset.type;\n    renderSourceOptions();\n  });\n});\n\nfunction renderSourceOptions() {\n  const optionsContainer = document.getElementById(''sourceOptions'');\n  const key = \\`æç´¢\\${currentType}\\`;\n  const sources = SOURCES[key] || [];\n  const savedValue = settings[currentType] || '''';\n  const selectedValues = savedValue === ''å¨é¨'' ? [''å¨é¨''] : (savedValue ? savedValue.split('','') : []);\n  \n  optionsContainer.innerHTML = '''';\n  \n  const allOption = document.createElement(''div'');\n  allOption.className = \\`source-option all \\${selectedValues.includes(''å¨é¨'') ? ''selected'' : ''''}\\`;\n  allOption.textContent = ''å¨é¨'';\n  allOption.addEventListener(''click'', () => selectOption(''å¨é¨''));\n  optionsContainer.appendChild(allOption);\n  \n  sources.forEach(source => {\n    const option = document.createElement(''div'');\n    option.className = \\`source-option \\${selectedValues.includes(source) ? ''selected'' : ''''}\\`;\n    option.textContent = source;\n    option.addEventListener(''click'', () => selectOption(source));\n    optionsContainer.appendChild(option);\n  });\n  \n  updateSelectedInfo();\n}\n\nfunction updateHiddenSettings() {\n  const jsonEl = document.getElementById(''settingsJson'');\n  if (jsonEl) {\n    jsonEl.textContent = JSON.stringify(settings);\n  }\n  \n  const typeMap = {\n    ''å°è¯´'': ''novelSource'',\n    ''å¬ä¹¦'': ''audioSource'',\n    ''æ¼«ç»'': ''comicSource'',\n    ''ç­å§'': ''dramaSource'',\n    ''æç´¢æ¨¡å¼'': ''searchModeValue'',\n    ''æ¾ç¤ºå¾ç'': ''showImageSwitchValue'',\n    ''å®æ´ç®ä»'': ''fullDescSwitchValue'',\n    ''åæ­¥ä¹¦æ¶'': ''syncBookshelfSwitchValue'',\n    ''åæ­¥å¼¹çª'': ''syncPopupSwitchValue'',\n    ''ç½ç»æ¨¡å¼'': ''networkModeValue'',\n    ''å¼ºå¶æç´¢'': ''forceSearchSwitchValue'',\n    ''ç®å½æ¾ç¤ºæ¥æº'': ''showSourceInTocValue''\n  };\n  \n  Object.keys(typeMap).forEach(type => {\n    const el = document.getElementById(typeMap[type]);\n    if (el) {\n      el.textContent = settings[type] != undefined ? settings[type] : (type.includes(''å¼å³'') ? ''false'' : ''å¨é¨'');\n    }\n  });\n}\n\nfunction setupBookSourceSettings() {\n  document.getElementById(''searchMode'').addEventListener(''change'', (e) => {\n    settings[''æç´¢æ¨¡å¼''] = e.target.value;\n    updateHiddenSettings();\n  });\n  \n  document.getElementById(''showImageSwitch'').addEventListener(''change'', (e) => {\n    settings[''æ¾ç¤ºå¾ç''] = e.target.checked ? ''true'' : ''false'';\n    updateHiddenSettings();\n  });\n  \n  document.getElementById(''fullDescSwitch'').addEventListener(''change'', (e) => {\n    settings[''å®æ´ç®ä»''] = e.target.checked ? ''true'' : ''false'';\n    updateHiddenSettings();\n  });\n  \n  document.getElementById(''syncBookshelfSwitch'').addEventListener(''change'', (e) => {\n    settings[''åæ­¥ä¹¦æ¶''] = e.target.checked ? ''true'' : ''false'';\n    updateHiddenSettings();\n    \n    const syncPopupSection = document.getElementById(''syncPopupSection'');\n    const syncPopupSwitch = document.getElementById(''syncPopupSwitch'');\n    if (e.target.checked) {\n      syncPopupSection.style.display = ''flex'';\n      if (settings[''åæ­¥å¼¹çª''] == undefined) {\n        settings[''åæ­¥å¼¹çª''] = ''true'';\n        syncPopupSwitch.checked = true;\n        updateHiddenSettings();\n      }\n    } else {\n      syncPopupSection.sty