      "init": "<js>\nlet moreSettings = getVariable(''æ´å¤è®¾ç½®'');\n\n\nfunction fetchBookDetail(result) {\n\t  let res = {};\n\t  //java.log(baseUrl)\n\t  //java.longToast(result)\n\t  if (String(baseUrl).startsWith(\"data:\")) {\n    res = JSON.parse(java.hexDecodeToString(result));\n    } else {\n    \treturn result;\n    \t}\n    const book_id = res.book_id;\n    const tab = res.tab;\n    const sources = res.sources || res.source;\n    const url = res.url;\n    let html = \"\";\n    const proxy  = moreSettings && moreSettings[''ç½ç»æ¨¡å¼''] || ''æå¡å¨'';\n\n    if (url && proxy == \"æ¬å°\") {\n        html = fetchHtmlWithFallback(url, sources);\n    }\n\n    const varia = getAndFormatCustomVariable();\n    const requestUrl = `/detail?book_id=${book_id}&source=${sources}&tab=${tab}&variable=${varia}`;\n\n    java.log(requestUrl);\n    return request(requestUrl, ''POST'', { html: html });\n}\n\nfunction fetchHtmlWithFallback(url, sources) {\n    let html;\n    let ck69 = '''';\n    let headers = {};\n    let op = '''';\n\n    if (sources == ''69ä¹¦å§'') {\n        ck69 = String(cookie.getCookie(''https://www.69shuba.com''));\n        headers = {\n            \"Referer\": url,\n            \"Cookie\": ck69,\n            \"User-Agent\": java.getWebViewUA()\n        };\n        op = JSON.stringify({ \"headers\": headers });\n        html = java.ajax(`${url},${op}`);\n    } else {\n        html = java.ajax(url);\n    }\n\n    if (html.includes(\"Just a moment...\") && sources == ''69ä¹¦å§'') {\n        cookie.removeCookie(''https://www.69shuba.com'');\n        java.longToast(''éè¦çäººéªè¯ï¼è¯·è¿å¥ä»»æä¹¦ç±è¯¦æé¡µè¿éªè¯'');\n        html = java.startBrowserAwait(url, \"éè¦çäººéªè¯ï¼è¯·è¿å¥ä»»æä¹¦ç±è¯¦æé¡µè¿éªè¯\").body();\n    }\n\n    return html;\n}\n\nfunction getAndFormatCustomVariable() {\n    let varia = String(book.getVariable(''custom''));\n    if (varia === ''null'') {\n        varia = '''';\n    }\n    return JSON.stringify({ ''custom'': varia });\n}\nfetchBookDetail(result)\n</js>$.data",
      "intro": "<js>\nconst {\n    source:sources,\n    book_id,\n    tab,\n    book_tts,\n    tags,\n    role,\n    last_chapter_title,\n    last_chapter_update_time,\n    word_number,\n    status,\n    score,\n    abstract,\n    copyright_info,\n    read_count,\n    read_count_all\n} = result;\nlet moreSettings = getVariable(''æ´å¤è®¾ç½®'');\n\n\nconst proxy = (moreSettings && moreSettings[''ç½ç»æ¨¡å¼''] || ''æå¡å¨'') == \"æ¬å°\" ? \"æ¬å°ç½ç»\" : \"æå¡å¨ç½ç»\";\n\nif ((book.readConfig && book.readConfig.useReplaceRule) == null) {\n    book.setUseReplaceRule(false);\n}\n\nlet nickname = ''è´¦å·ç¶æï¼â ï¸ æªç»å½ | ç¹å»å³ä¸è§ ð ç»å½'';\nlet qttoken = getToken();\nif (qttoken.length > 10) {\n     nickname = ''è´¦å·ç¶æï¼âå·²ç»å½'';\n}\ntry {\n    const user_info = JSON.parse(request(`/get_avatar`, ''GET''));\n    if (user_info.code === 0) {\n        nickname = user_info.nickname \n            ? `æ¬¢è¿åæ¥ï¼${user_info.nickname}`\n            : `æ¬¢è¿åæ¥ï¼${user_info.email}(è¯·åå¾ç¨æ·åå°è®¾ç½®ç¨æ·å)`;\n    }\n} catch (e) {\n    \n}\n\nconst loginStatus = nickname;\nconst lightDivider = \"âï¸ââââââââï¸ââââââââï¸\";\nconst heavyDivider = \"&lrm;\\n&lrm;\";\n\nconst isValid = (value) => String(value).length > 1;\nlet ctitle =  book.durChapterTitle || ''æªå¼å§'';\n\nconst formatAbstract = (text) => {\n    return text.split(\"\\n\").map(line => `    ${line}`).join(\"\\n\");\n};\n\nconst buildBasicInfo = (items) => {\n    let info = \"\";\n    for (let [value, prefix, icon] of items) {\n        if (isValid(value)) {\n            info += `    ${icon} ${prefix} ${value}\\n`;\n        }\n    }\n    return info;\n};\n\nlet info = `\n    ð¡ å½åæå¡ï¼${BaseUrl()}\n    ð ${loginStatus}\n    ð· æ°æ®æ¥æºï¼${sources}\n    ð å½åæ¨¡å¼ï¼${tab}\n    âï¸ è®¿é®æ¨¡å¼ï¼${proxy}\n    ð éè¯»è³ï¼${ctitle}\n`;\n\nif (tab == \"å¬ä¹¦\") {\n    let toneId = String(book.getVariable(''custom'')) || ''4'';\n    if (isValid(book_tts)) {\n        info += `${lightDivider}\n    ðµ é³è²éç½®ï¼${toneId}\n    â¨ AIé³è²è¯·ç¹å»å³ä¸è§ä¹¦ç±åéå¡«åç¸å³å¼ï¼çäººå¬ä¹¦è¯·éæ°æç´¢éæ©å¸¦æä¸»æ­çä¹¦ç±\n    ${book_tts}\n`;\n    }\n}\n\nconst fullBasicInfo = buildBasicInfo([\n    [tags, \"ä¹¦ç±åç±»ï¼\", \"ð\"],\n    [role, \"ä¹¦ç±ä¸»è§ï¼\", \"ð\"],\n    [last_chapter_title, \"ææ°ç« èï¼\", \"ð\"],\n    [last_chapter_update_time, \"æ´æ°æ¶é´ï¼\", \"â³\"],\n    [word_number, \"ä¹¦ç±å­æ°ï¼\", \"ð\"],\n    [status, \"ä¹¦ç±ç¶æï¼\", \"ð©\"],\n    [score, \"ä¹¦ç±è¯åï¼\", \"â­\"],\n    [read_count, \"ä»éè¯»äººæ°ï¼\", \"ð\"],\n    [read_count_all, \"æ»éè¯»äººæ°ï¼\", \"ð\"]\n]);\n\nif (fullBasicInfo) {\n    info += `${lightDivider}\\n${fullBasicInfo}`;\n}\n\nif (isValid(abstract)) {\n    info += `${heavyDivider}\n    ð ä¹¦ç±ç®ä»ï¼\n${formatAbstract(abstract)}\n`;\n} else {\n    info += heavyDivider;\n}\n\nif (isValid(copyright_info)) {\n    info += `${lightDivider}\n    Â© ${copyright_info}\n`;\n} else {\n    info += lightDivider;\n}\n\ninfo += `\n${heavyDivider}\n    æ°æ®æ´æ°äº ${new Date().toLocaleString()}\n`;\n\nconst abstractMode = moreSettings && moreSettings[''å®æ´ç®ä»''] || ''true'';\nif (abstractMode == \"false\") {\n    const simplifiedBasicInfo = buildBasicInfo([\n        [last_chapter_title, \"ææ°ç« èï¼\", \"ð\"],\n        [last_chapter_update_time, \"æ´æ°æ¶é´ï¼\", \"â³\"],\n        [word_number, \"ä¹¦ç±å­æ°ï¼\", \"ð\"],\n        [status, \"ä¹¦ç±ç¶æï¼\", \"ð©\"],\n        [score, \"ä¹¦ç±è¯åï¼\", \"â­\"]\n    ]);\n    \n    info = `\\n&lrm;${isValid(abstract) ? `ð ä¹¦ç±ç®ä»ï¼\\n${formatAbstract(abstract)}\\n${heavyDivider}` : ''''}\nð· æ°æ®æ¥æºï¼${sources}\n${simplifiedBasicInfo}`;\n\n} else {\n    info = info.split(\"\\n\").map(line => line.replace(/^ {4}/, \"\")).join(\"\