weight: 600;\n      color: var(--text-main);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .history-header h2 i {\n      color: #4e6ef2;\n    }\n\n    .toggle-history {\n      background: none;\n      border: none;\n      color: var(--text-secondary);\n      cursor: pointer;\n      font-weight: 500;\n      display: flex;\n      align-items: center;\n      gap: 4px;\n      font-size: 0.85rem;\n      transition: color 0.2s ease;\n    }\n\n    .toggle-history:hover {\n      color: #4e6ef2;\n    }\n\n    .history-content {\n      padding: 0 16px;\n      max-height: 0;\n      overflow: hidden;\n      transition: max-height 0.4s ease, padding 0.4s ease;\n    }\n\n    .history-content.expanded {\n      max-height: 60vh;\n      overflow-y: auto;\n      padding: 16px;\n      scrollbar-width: thin;\n      scrollbar-color: #4e6ef2 #f0f0f0;\n    }\n\n    .history-content.expanded::-webkit-scrollbar {\n      width: 6px;\n    }\n\n    .history-content.expanded::-webkit-scrollbar-track {\n      background: #f0f0f0;\n      border-radius: 4px;\n    }\n\n    .history-content.expanded::-webkit-scrollbar-thumb {\n      background: #4e6ef2;\n      border-radius: 4px;\n    }\n\n    .history-content.expanded::-webkit-scrollbar-thumb:hover {\n      background: #3a56d0;\n    }\n\n    .history-item {\n      margin-bottom: 16px;\n      padding-bottom: 16px;\n      border-bottom: 1px dashed var(--border-color);\n    }\n\n    .history-item:last-child {\n      border-bottom: none;\n      margin-bottom: 0;\n      padding-bottom: 0;\n    }\n\n    .history-date {\n      font-weight: 600;\n      color: var(--text-main);\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 4px;\n      font-size: 0.9rem;\n      background: rgba(78, 110, 242, 0.05);\n      padding: 6px 10px;\n      border-radius: 6px;\n    }\n\n    .history-text {\n      margin: 8px 0;\n      padding-left: 16px;\n      line-height: 1.4;\n      color: var(--text-secondary);\n      position: relative;\n      font-size: 0.9rem;\n      white-space: pre-wrap;\n      word-break: break-word;\n    }\n\n    .history-text::before {\n      content: ''â¢'';\n      position: absolute;\n      left: 0;\n      color: #4e6ef2;\n      font-weight: bold;\n      font-size: 1.2rem;\n      line-height: 1;\n    }\n\n    /* æé®ç» */\n    .button-group {\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n      margin-bottom: 16px;\n    }\n\n    .button {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 10px;\n      padding: 14px 28px;\n      text-align: center;\n      font-size: 1rem;\n      border: none;\n      border-radius: 12px;\n      text-decoration: none;\n      background: var(--primary-gradient);\n      color: white;\n      font-weight: 600;\n      transition: all 0.3s ease;\n      box-shadow: var(--shadow);\n      position: relative;\n      overflow: hidden;\n      cursor: pointer;\n    }\n\n    .button i {\n      font-size: 1rem;\n    }\n\n    .button::after {\n      content: '''';\n      position: absolute;\n      top: -50%;\n      left: -50%;\n      width: 200%;\n      height: 200%;\n      background: rgba(255, 255, 255, 0.1);\n      transform: rotate(30deg);\n      transition: all 0.6s ease;\n      pointer-events: none;\n    }\n\n    .button:hover {\n      transform: translateY(-3px);\n      box-shadow: var(--shadow-hover);\n    }\n\n    .button:hover::after {\n      transform: rotate(30deg) translate(20%, 20%);\n    }\n\n    .button:active {\n      transform: scale(0.95);\n    }\n\n    /* éè¯¯ç¶æ */\n    .error-state {\n      text-align: center;\n      padding: 40px 20px;\n      color: var(--text-main);\n    }\n\n    .error-icon {\n      font-size: 64px;\n      margin-bottom: 20px;\n      color: var(--error-color);\n    }\n\n    .error-text {\n      font-size: 16px;\n      line-height: 1.6;\n      margin-bottom: 20px;\n    }\n\n    .retry-button {\n      background: var(--primary-gradient);\n      color: white;\n      padding: 12px 30px;\n      border-radius: 12px;\n      border: none;\n      font-weight: 600;\n      cursor: pointer;\n      transition: all 0.3s ease;\n      font-size: 14px;\n      box-shadow: var(--shadow);\n    }\n\n    .retry-button:hover {\n      transform: translateY(-2px);\n      box-shadow: var(--shadow-hover);\n    }\n\n    .retry-button:active {\n      transform: scale(0.95);\n    }\n\n    /* è£é¥°åç´  */\n    .decoration {\n      position: absolute;\n      z-index: 0;\n      pointer-events: none;\n    }\n\n    .decoration.circle {\n      width: 120px;\n      height: 120px;\n      border-radius: 50%;\n      background: rgba(107, 45, 216, 0.05);\n      top: 10%;\n      left: 10%;\n    }\n\n    .decoration.square {\n      width: 80px;\n      height: 80px;\n      transform: rotate(45deg);\n      background: rgba(78, 110, 242, 0.05);\n      bottom: 10%;\n      right: 10%;\n    }\n\n    /* ååºå¼ */\n    @media (max-width: 768px) {\n      body {\n        padding: 12px;\n      }\n\n      .container {\n        max-width: 100%;\n        border-radius: 20px;\n      }\n\n      .header {\n        padding: 20px 15px;\n      }\n\n      .header h1 {\n        font-size: 1.3rem;\n      }\n\n      .header-icon {\n        font-size: 40px;\n      }\n\n      .version-comparison {\n        flex-direction: row;\n        flex-wrap: nowrap;\n        gap: 10px;\n        padding: 12px;\n        margin-top: 6px;\n        overflow-x: auto;\n      }\n\n      .version-card {\n        min-width: 45%;\n        padding: 26px 12px 12px;\n      }\n\n      /* ç§»å¨ç«¯åå¼±å¼å¸å¨æ */\n      .version-card.latest-version {\n        animation: gradientAnimation 6s ease infinite;\n      }\n\n      .version-status {\n        top: 5px;\n        right: 5px;\n        padding: 2px 5px;\n        font-size: 0.6rem;\n      }\n\n      .version-number {\n        font-size: 1.1rem;\n      }\n\n      .version-card.latest-version .version-number {\n        font-size: 1.2rem;\n      }\n\n      .update-header h2, .history-header h2 {\n        font-size: 0.9rem;\n      }\n\n      .button {\n        padding: 12px 24px;\n        font-size: 0.95rem;\n      }\n\n      .history-content.expanded {\n        max-height: 50vh;\n        -webkit-overflow-scrolling: touch;\n      }\n    }\n\n    @media (max-width: 380px) {\n      .header h1 {\n        font-size: 1.2rem;\n      }\n\n      .version-number {\n        font-size: 1rem;\n      }\n\n      .version-card.latest-version .version-number {\n        font-size: 1.1rem;\n      }\n\n      .button {\n        padding: 11px;\n        font-size: 0.9rem;\n      }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"decoration circle\"></div>\n  <div class=\"decoration square\"></div>\n\n  <div id=\"loading\" class=\"loading-wrapper\">\n    <div class=\"loading-spinner\"></div>\n    <div class=\"loading-text\"><i class=\"fas fa-search\"></i> æ­£å¨æ£æ¥æ´æ°...</div>\n  </div>\n\n  <div class=\"container\" id=\"container\">\n    <div class=\"header\">\n      <div class=\"header-icon\"><i class=\"fas fa-book\"></i></div>\n      <h1>åéä¹¦æºæ´æ°</h1>\n<p>æ¨èä½¿ç¨éè¯»Sigmaçæ¬<br>æ­£å¼çå¯è½å­å¨å¼å®¹æ§é®é¢-<a href=''https://legado.gyks.cf'' style=''text-decoration: none; color: #2D9D78; font-weight: 600;''>ä¸è½½</a></p>\n    </div>\n\n    <div class=\"version-comparison\">\n      <div class=\"version-card current-version\">\n        <div class=\"version-status status-outdated\" id=\"currentStatus\">å¾æ£æ¥</div>\n        <h3><i class=\"fas fa-cube\"></i> å½åçæ¬</h3>\n        <div class=\"version-number\" id=\"currentVersion\">-</div>\n        <div class=\"version-date\">æ¨çå½åçæ¬</div>\n      </div>\n\n      <div class=\"version-indicator update-needed\" id=\"versionIndicator\" style=\"display: none;\">\n        <i class=\"fas fa-arrow-right\"></i>\n      </div>\n\n      <div class=\"version-card latest-version\">\n        <div class=\"version-status status-latest\" id=\"latestStatus\">ææ°çæ¬</div>\n        <h3><i class=\"fas fa-star\"></i> ææ°çæ¬</h3>\n        <div class=\"version-number\" id=\"latestVersion\">-</div>\n        <div class=\"version-date\">å¯ç¨ææ°çæ¬</div>\n      </div>\n    </div>\n\n    <div class=\"content-container\">\n      <div class=\"status-alert\" id=\"statusAlert\" style=\"display: none;\"></div>\n\n      <div id=\"latestLogContainer\" style=\"display: none;\">\n        <div class=\"update-container\">\n          <div class=\"update-header\">\n            <h2><i class=\"fas fa-bolt\"></i> ææ°æ´æ°</h2>\n            <div class=\"update-tag\">ææ°åå¸</div>\n          </div>\n          <div class=\"update-content\">\n            <div class=\"update-date\" id=\"latestLogDate\"></div>\n            <div class=\"update-text\" id=\"latestLogContent\"></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"button-group\" id=\"buttonGroup\" style=\"display: none;\"></div>\n\n      <div class=\"history-container\" id=\"logs\" style=\"display: none;\">\n        <div class=\"history-header\" onclick=\"toggleLogs()\">\n          <h2><i class=\"fas fa-history\"></i> åå²æ´æ° <span id=\"historyCount\"></span></h2>\n          <button class=\"toggle-history\" id=\"toggleButton\">\n            <span id=\"toggleText\">å±å¼åå²</span>\n            <i class=\"fas fa-chevron-down\" id=\"toggleIcon\"></i>\n          </button>\n        </div>\n        <div class=\"history-content\" id=\"logList\"></div>\n      </div>\n    </div>\n  </div>\n\n  <script>\n  let logsCollapsed = true;\n\n  function toggleLogs() {\n    logsCollapsed = !logsCollapsed;\n    const logList = document.getElementById(''logList'');\n    const toggleText = document.getElementById(''toggleText'');\n    const toggleIcon = document.getElementById(''toggleIcon'');\n    \n    if (logsCollapsed) {\n      logList.classList.remove(''expanded'');\n      toggleText.textContent = ''å±å¼åå²'';\n      toggleIcon.className = ''fas fa-chevron-down'';\n    } else {\n      logList.classList.add(''expanded'');\n      toggleText.textContent = ''æ¶èµ·åå²'';\n      toggleIcon.className = ''fas fa-chevron-up'';\n    }\n  }\n\n  (async function() {\n    const loading = document.getElementById(''loading'');\n    const container = document.getElementById(''container'');\n    const currentVersion = document.getElementById(''currentVersion'');\n    const latestVersion = document.getElementById(''latestVersion'');\n    const currentStatus = document.getElementById(''currentStatus'');\n    const latestStatus = document.getElementById(''latestStatus'');\n    const versionIndicator = document.getElementById(''versionIndicator'');\n    const statusAlert = document.getElementById(''statusAlert'');\n    const buttonGroup = document.getElementById(''buttonGroup'');\n    const latestLogContainer = document.getElementById(''latestLogContainer'');\n    const latestLogDate = document.getElementById(''latestLogDate'');\n    const latestLogContent = document.getElementById(''latestLogContent'');\n    const logsContainer = document.getElementById(''logs'');\n    const logList = document.getElementById(''logList'');\n    const historyCount = document.getElementById(''historyCount'');\n\n    const localVer = ''${String(localVersion)}'';\n    let hosts = \\`${hostsbk}\\`;\n    hosts = hosts.split('','');\n    \nconst icons = [''box'', ''satellite'', ''link'', ''bolt'', ''globe'', ''broadcast-tower''];\n\n// åå§åserverConfig\nconst serverConfig = {\n    main: {\n        name: ''ä¸»çº¿è·¯å¯¼å¥'',\n        icon: ''rocket'',\n        baseUrl: ''https://sy.gyks.cf'',\n        downloadPath: ''/download/åéèå.json''\n    }\n};\n\nhosts.forEach((host, index) => {\n    const backupNumber = index + 1;\n    const key =\\`å¤ç¨çº¿è·¯\\${backupNumber}\\`;\n\n    serverConfig[key] = {\n        name: \\`\\${key}å¯¼å¥\\`,\n        icon: icons[index] || ''broadcast-tower'',\n        baseUrl: host,\n        downloadPath: ''/sy/download/åéèå.json''\n    };\n});\n\n    // çæ¬æ¯è¾å½æ°\n    function compareVersions(vs) {\n      const normalize = (v) => {\n        return v.split(''.'').map(n => {\n          const num = parseInt(n, 10);\n          return isNaN(num) ? 0 : num;\n        });\n      };\n\n      const parts1 = normalize(localVer);\n      const parts2 = normalize(vs);\n      const maxLength = Math.max(parts1.length, parts2.length);\n      \n      for (let i = 0; i < maxLength; i++) {\n        const num1 = parts1[i] || 0;\n        const num2 = parts2[i] || 0;\n        if (num1 > num2) return 1;\n        if (num1 < num2) return -1;\n      }\n      return 0;\n    }\n\nasync function fetchVersionData() {\n  const serversToCheck = Object.values(serverConfig);\n  \n  for (const server of serversToCheck) {\n    try {\n      const apiPath = server.baseUrl.includes(''sy.gyks.cf'') \n        ? ''/fils-groups'' \n        : ''/get_sy_log'';\n      \n      const response = await fetch(server.baseUrl + apiPath, { timeout: 2000 });\n      if (response.ok) {\n        return await response.json();\n      }\n    } catch (e) {\n      console.warn(\\`æ¥å£å¤±è´¥ï¼\\${server.baseUrl}\\`, e);\n    }\n  }\n  throw new Error(''æææ´æ°æ¥å£é½è¯·æ±å¤±è´¥'');\n}\n\n\n    function showError(message) {\n      loading.innerHTML = \\`\n        <div class=\"error-state\">\n          <div class=\"error-icon\"><i class=\"fas fa-exclamation-triangle\"></i></div>\n          <div class=\"error-text\">\\${message}</div>\n          <button class=\"retry-button\" onclick=\"location.reload()\"><i class=\"fas fa-redo\"></i> éè¯</button>\n        </div>\n      \\`;\n    }\n\n    try {\n      const data = await fetchVersionData();\nconst legadoData = (data.data && data.data.find(item => item.key == ''legado_aggregate'')) || {};\nconst cloudVersion = String(legadoData.current_version || '''');\nconst updateLog = legadoData.update_log || [];\n\n// æ¾ç¤ºçæ¬ä¿¡æ¯\ncurrentVersion.textContent = \\`v\\${localVer}\\`;\nlatestVersion.textContent = \\`v\\${cloudVersion}\\`;\n\n// å¤çæ¥å¿ï¼update_log æ¯æ°ç»æ ¼å¼ï¼\nif (updateLog.length > 0) {\n// æ¾ç¤ºææ°æ¥å¿\nconst latestLog = updateLog[0];\nlatestLogDate.innerHTML = \\`<i class=\"fas fa-calendar-alt\"></i> v\\${latestLog.version}\\`;\nlatestLogContent.innerHTML = latestLog.log;\nlatestLogContainer.style.display = ''block'';\n\n// æ¾ç¤ºåå²æ¥å¿\nif (updateLog.length > 1) {\nconst historyLogs = updateLog.slice(1);\nhistoryCount.textContent = \\`(\\${historyLogs.length}æ¡)\\`;\nlogList.innerHTML = historyLogs.map(item => \\`\n<div class=\"history-item\">\n    <div class=\"history-date\">\n    <i class=\"fas fa-calendar-day\"></i>\n    <span>v\\${item.version}</span>\n    </div>\n    <div class=\"history-text\">\\${item.log}</div>\n</div>\n\\`).join('''');\nlogsContainer.style.display = ''block'';\n}\n}\n\n// æ£æ¥æ´æ°ç¶æ\nconst compareResult = compareVersions(cloudVersion);\n\n// æ¾ç¤ºçæ¬æç¤ºå¨\nversionIndicator.style.display = ''flex'';\n\nif (compareResult === -1) {\n// éè¦æ´æ°\ncurrentStatus.textContent = ''å¾æ´æ°'';\ncurrentStatus.className = ''version-status status-outdated'';\nversionIndicator.className = ''version-indicator update-needed'';\nversionIndicator.innerHTML = ''<i class=\"fas fa-arrow-right\"></i>'';\n\n// ä½¿ç¨ç»ä¸éç½®çæä¸è½½æé®\nbuttonGroup.innerHTML = Object.values(serverConfig).map(server => {\nconst fullUrl = server.baseUrl + server.downloadPath;\nreturn \\`\n<a href=\"yuedu://booksource/importonline?src=\\${encodeURIComponent(fullUrl)}\" class=\"button\">\n    <i class=\"fas fa-\\${server.icon}\"></i>\n    <span>\\${server.name}</span>\n</a>\n\\`;\n}).join('''');\nbuttonGroup.style.display = ''flex'';\n} else {\n// å·²æ¯ææ°çæ¬\ncurrentStatus.textContent = ''ææ°'';\ncurrentStatus.className = ''version-status status-latest'';\nversionIndicator.className = ''versi