t.getElementById(''lastCheckTime'').textContent = \\`æåæ£æµ: \\${now.toLocaleTimeString()}\\`;\n}\n\ndocument.getElementById(''refreshBtn'').addEventListener(''click'', checkServers);\n\ndocument.addEventListener(''DOMContentLoaded'', () => {\n  renderServerList();\n  document.getElementById(''currentServer'').textContent = currentServer;\n  checkServers();\n  \n  // åå§åèªå¨åæ¢å¼å³\n  const autoSwitchToggle = document.getElementById(''autoSwitchToggle'');\n  const autoSwitchValue = document.getElementById(''autoSwitchValue'').textContent;\n  autoSwitchToggle.checked = autoSwitchValue !== ''false'';\n  \n  // çå¬å¼å³åå\n  autoSwitchToggle.addEventListener(''change'', (e) => {\n    document.getElementById(''autoSwitchValue'').textContent = e.target.checked ? ''true'' : ''false'';\n  });\n  \n  // åå§åè¶æ¶èªå¨åæ¢å¼å³\n  const timeoutSwitchToggle = document.getElementById(''timeoutSwitchToggle'');\n  const timeoutSwitchValue = document.getElementById(''timeoutSwitchValue'').textContent;\n  timeoutSwitchToggle.checked = timeoutSwitchValue !== ''false'';\n  \n  // çå¬è¶æ¶èªå¨åæ¢å¼å³åå\n  timeoutSwitchToggle.addEventListener(''change'', (e) => {\n    document.getElementById(''timeoutSwitchValue'').textContent = e.target.checked ? ''true'' : ''false'';\n  });\n  \n  // åå§åè¶æ¶æ¶é´ä¸ææ¡\n  const timeoutSelect = document.getElementById(''timeoutSelect'');\n  const timeoutValue = document.getElementById(''timeoutValue'').textContent;\n  timeoutSelect.value = timeoutValue;\n  \n  // çå¬è¶æ¶æ¶é´åå\n  timeoutSelect.addEventListener(''change'', (e) => {\n    document.getElementById(''timeoutValue'').textContent = e.target.value;\n  });\n  \n  // åå§ååæ¢æéå¼¹çªå¼å³\n  const notifySwitchToggle = document.getElementById(''notifySwitchToggle'');\n  const notifySwitchValue = document.getElementById(''notifySwitchValue'').textContent;\n  notifySwitchToggle.checked = notifySwitchValue !== ''false'';\n  \n  // çå¬åæ¢æéå¼¹çªå¼å³åå\n  notifySwitchToggle.addEventListener(''change'', (e) => {\n    document.getElementById(''notifySwitchValue'').textContent = e.target.checked ? ''true'' : ''false'';\n  });\n});\n</script>\n</body>\n</html>\n    `;\n    let body;\n    try {\n        body = java.startBrowserAwait(`data:text/html;base64,${java.base64Encode(html)}`, ''åéæå¡å¨è®¾ç½®'', false).body();\n    } catch (e) {\n        let islyc = this.checkEnv()\n        if (islyc == \"å®å\") {\n            this.switchToNextLine();\n        } else {\n            java.longToast(\"\\nè¯·ç¹å»é¡µé¢å³ä¸è§âæè½è®¾ç½®æåå¦~\");\n        }\n        return;\n    }\n    \n    let host = hostsbk[0];\n    let autoSwitch = ''true'';\n    let timeoutSwitch = ''true'';\n    let timeout = ''10'';\n    let notifySwitch = ''false'';\n    try {\n        const getSpanText = (spanId) => {\n            const regex = new RegExp(''id=\"'' + spanId + ''\"\\s*>\\s*([^<]*?)\\s*<\\/span>'');\n            const match = body.match(regex);\n            return match ? match[1].trim() : \"\";\n        };\n        host = getSpanText(''serverValue'') || hostsbk[0];\n        autoSwitch = getSpanText(''autoSwitchValue'') || ''true'';\n        timeoutSwitch = getSpanText(''timeoutSwitchValue'') || ''true'';\n        timeout = getSpanText(''timeoutValue'') || ''10'';\n        notifySwitch = getSpanText(''notifySwitchValue'') || ''false'';\n    } catch (e) {\n        host = hostsbk[0];\n        autoSwitch = ''true'';\n        timeoutSwitch = ''true'';\n        timeout = ''10'';\n        notifySwitch = ''true'';\n    }\n    const settingsText = `çº¿è·¯: ${host}\\nå¤±è´¥èªå¨åæ¢: ${autoSwitch == ''true'' ? ''å¼å¯'' : ''å³é­''}\\nè¶æ¶èªå¨åæ¢: ${timeoutSwitch == ''true'' ? ''å¼å¯'' : ''å³é­''}\\nè¶æ¶æ¶é´: ${timeout}ç§\\nåæ¢æéå¼¹çª: ${notifySwitch == ''true'' ? ''å¼å¯'' : ''å³é­''}`;\n    java.longToast(\"\\n\" + settingsText);\n    this.