INSERT INTO public.book_sources (id, title, source_json, description, install_id, created_at, updated_at, user_id, supported_types, source_code, review_status, review_note, reviewed_by, reviewed_at, visibility, enabled, last_test_status, last_test_at, last_test_message, origin_source_id) VALUES ('src_48c4ab0d6f86', '大灰狼', '[{"bookSourceComment":"更新日志请点击登录，更新书源中查看\n\n基础使用教程：\n1、搜索：\n    1)基础搜索：在发现页长按该书源，点击搜索，直接搜，搜索范围(全部来源小说)\n    2)进阶搜索：在登陆-书源设置中选择指定模式\/来源，可搜索指定模式\/来源内容\n    3)快捷搜索：使用特殊关键词(x,t,m,d,@)搜索\n         x:书名@来源  如(x:十日终焉@番茄)\n         t:书名@来源  如(t:十日终焉@番茄)\n         m:书名@来源  如(m:十日终焉@番茄)\n         d:书名@来源  如(d:十日终焉@番茄)\n         其中：x表示小说(可省略)，t表示听书，m表示漫画，d表示短剧\n         冒号支持中文英文\n         \n2、发现页：\n    在书源设置中选择指定模式或者单个来源，然后刷新发现页即可\n    \n3、更多使用方式长按发现页书源选择登录一目了然\n4、用户后台有视频教程\n         ","bookSourceGroup":"大灰狼聚合","bookSourceName":"🍅大灰狼聚合5.5.22(vip完全版)","bookSourceType":0,"bookSourceUrl":"大灰狼融合VIP5.0","bookUrlPattern":"https?:\\\/\\\/(?:[a-zA-Z0-9-]+\\.)+[a-zA-Z0-9-]+(?::\\d+)?\\\/detail.*","customButton":false,"customOrder":4,"enabled":true,"enabledCookieJar":false,"enabledExplore":true,"eventListener":false,"exploreUrl":"<js>\nvar open_argument = source.getVariable();\nif (!open_argument || open_argument == '''') {\n    var initData = {\n        tab: \"小说\",\n        tone_id: \"默认音色\",\n        server: host[0],\n        sources: \"番茄\",\n        source_type: \"男频\",\n        find_source: \"番茄\",\n        find_tab: \"小说\",\n        fqpara: \"on\"\n    };\n    source.setVariable(JSON.stringify(initData));\n    open_argument = source.getVariable();\n}\nvar base_url = getArguments(open_argument, ''server'') || host[0];\nvar ms = getArguments(open_argument, ''tone_id'') || '''';\nvar source_type = getArguments(open_argument, ''source_type'') || ''男频'';\nvar tab = getArguments(open_argument, ''find_tab'') || getArguments(open_argument, ''tab'') || ''小说'';\nvar sources =  getArguments(open_argument, ''sources'') || ''番茄'';\nvar fxyjr = getArguments(open_argument, ''fxyjr'');\n\n\nfunction checkEnv() {\n    let isModified = false;\n    try {\n        new Packages.io.legato.kazusa.utils.TimeoutCancellationException('''');\n        isModified = true;\n    } catch (e) {\n        isModified = typeof source.loginUi == ''function'' ? false : true;\n    }\n\n    return isModified;\n}\n\nvar islyc = checkEnv();\nlet device_type = ''安卓'';\ntry {\n\t  try {\n\t  java.qread();\n\t  device_type =\"轻阅读\";\n\t  } catch {\n\t  \tjava.deviceID();\n    device_type = \"苹果\";\n\t  \t}\n    \n} catch (e) {\n    try {\n        java.androidId();\n        device_type = \"安卓\";\n    } catch (e) {\n        device_type = \"安卓\";\n    }\n}\n\nif (((islyc&&device_type!=''苹果'') || device_type==''轻阅读'') && fxyjr != \"on\"){\n\tsources = getArguments(open_argument, ''find_source'') || sources;\n\tsetArguments(''find_source'', sources);\n\t}\nvar sdtoken;\ntry {\n    var loginInfoMap = source.getLoginInfoMap ? source.getLoginInfoMap() : {};\n    sdtoken = String(loginInfoMap[''手动填写番茄token(可不填)''] || '''');\n} catch (e) {\n    sdtoken = '''';\n}\n\nvar rawCookie = getFanqieCookie() || sdtoken;\nvar match = rawCookie.match(\/sessionid=[^;]+\/);\nvar fqcookie = match ? match[0] : '''';\nvar fqssionid = '''';\nif (!fqcookie && (sources == ''番茄'' || sources == ''全部'')) {\n    java.toast(''您还未登陆番茄账号，无法同步数据哦！'');\n} else {\n    fqssionid = getSessionId(fqcookie)\n}\nvar fqsjurl = base_url + \"\/bookshelf?page={{page}}&ssionid=\" + fqssionid;\nvar fqtjurl = base_url + \"\/fqrecommend?page={{page}}&ssionid=\" + fqssionid;\nvar fqlsurl = base_url + \"\/fqhistory?page={{page}}&ssionid=\" + fqssionid;\n\nvar groupDatas = [];\nvar infoData = [ ];\nif (sources == ''番茄'' || sources == ''全部'') {\ninfoData = [{\n        \"title\": \"登录番茄\",\n        \"url\": ''{\\{java.startBrowser(\"https:\/\/fanqienovel.com\/\",\"番茄登录\");}}'',\n        \"style\": {\n            \"layout_flexGrow\": 1,\n            \"layout_flexBasisPercent\": 0.45\n        }\n    }];\n}\n\nvar hasValidCookie = fqcookie.length > 0;\n\nif (hasValidCookie && (sources == ''番茄'' || sources == ''全部'')) {\n    function groupQuery() {\n        try {\n            var url = base_url + \"\/group_name?ssionid=\" + fqssionid;\n            var res = java.ajax(url);\n            var response = JSON.parse(res);\n\n            if (!(response && response.data)) {}\n\n            response.data.forEach(function(group) {\n                var keys = Object.keys(group);\n                if (keys.length > 0) {\n                    var key = keys[0];\n                    var value = group[key];\n                    if (value && value.length) {\n                        var option = {\n                            \"method\": \"POST\",\n                            \"body\": {\n                                \"book_ids\": value,\n                                \"page\": \"{{page}}\"\n                            }\n                        };\n                        groupDatas.push({\n                            title: key,\n                            url: base_url + \"\/bookshelf,\" + JSON.stringify(option),\n                            style: {\n                                layout_flexGrow: 1,\n                                layout_flexBasisPercent: 0.45\n                            }\n                        });\n                    }\n                }\n            });\n\n            if (groupDatas.length % 2 !== 0) {\n                groupDatas.push({\n                    title: \"--\",\n                    url: \"\",\n                    style: {\n                        layout_flexGrow: 1,\n                        layout_flexBasisPercent: 0.45\n                    }\n                });\n            }\n        } catch (e) {\n            java.longToast(\"番茄登录过期，已隐藏番茄书架\" + fqssionid);\n        }\n    }\n\n    try {\n        java.longToast(\"正在加载分组数据...\");\n        var userUrl = base_url + \"\/fquser?ssionid=\" + fqssionid;\n        var userRes = java.ajax(userUrl);\n        var userD